svg.script:
(() => {
  "use strict";

  const BASE =
    "https://cdn.jsdelivr.net/gh/" +
    "roccohebert687-cloud/Real-Auto-update@main/";

  const URL = BASE + "updated-site.html";

  const root = document.getElementById("root");
  const container = document.getElementById("container");
  const frame = document.getElementById("site");
  const status = document.getElementById("status");

  let currentHTML = null;
  let checking = false;
  let statusTimer;

  function fitWindow() {
    const width = window.innerWidth;
    const height = window.innerHeight;

    root.setAttribute("width", width);
    root.setAttribute("height", height);
    container.setAttribute("width", width);
    container.setAttribute("height", height);
  }

  function showStatus(message, persistent = false) {
    clearTimeout(statusTimer);
    status.textContent = message;
    status.style.display = "block";

    if (!persistent) {
      statusTimer = setTimeout(() => {
        status.style.display = "none";
      }, 5000);
    }
  }

  function displayHTML(html) {
    const baseTag = '<base href="' + BASE + '">';

    const resetStyle = `
      <style id="svg-window-reset">
        html {
          width: 100% !important;
          min-height: 100% !important;
          margin: 0 !important;
          padding: 0 !important;
          border: 0 !important;
          background-color: #07120c !important;
        }

        body {
          width: 100% !important;
          min-height: 100vh !important;
          margin: 0 !important;
          padding: 0 !important;
          border: 0 !important;
          background-color: #07120c !important;
        }
      </style>
    `;

    let output;

    if (/<head\b[^>]*>/i.test(html)) {
      output = html.replace(
        /<head\b[^>]*>/i,
        match => match + baseTag
      );
    } else {
      output = baseTag + html;
    }

    if (/<\/head\s*>/i.test(output)) {
      output = output.replace(
        /<\/head\s*>/i,
        resetStyle + "</head>"
      );
    } else {
      output = resetStyle + output;
    }

    frame.srcdoc = output;
  }

  async function checkForUpdates() {
    if (checking || document.hidden) return;
    checking = true;

    const controller = new AbortController();
    const timeout = setTimeout(
      () => controller.abort(),
      20000
    );

    try {
      const response = await fetch(URL, {
        cache: "no-store",
        signal: controller.signal
      });

      if (!response.ok) {
        throw new Error("HTTP " + response.status);
      }

      const html = await response.text();

      if (!/<html\b|<!doctype\s+html/i.test(html)) {
        throw new Error("Expected an HTML page.");
      }

      if (html !== currentHTML) {
        const firstLoad = currentHTML === null;

        displayHTML(html);
        currentHTML = html;

        showStatus(
          firstLoad ? "Site loaded" : "Updated version loaded"
        );
      }
    } catch (error) {
      showStatus(
        currentHTML === null
          ? "Loading failed: " + error.message +
            ". Retrying every 60 seconds."
          : "Update unavailable; keeping current version.",
        currentHTML === null
      );
    } finally {
      clearTimeout(timeout);
      checking = false;
    }
  }

  fitWindow();
  window.addEventListener("resize", fitWindow);

  checkForUpdates();
  setInterval(checkForUpdates, 60000);

  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) {
      fitWindow();
      checkForUpdates();
    }
  });
})();
